{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Dexketoprofen, a chiral methyl-phenyl carboxylic acid analogue, was detected in human CSF after systemic dosing, directly demonstrating CNS access despite an acidic group; this supports meaningful brain penetration for the query's related chiral phenethylamide scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Hydroxybupropion, a chlorophenyl-containing small molecule, achieved a rat brain Kp,uu of 1.7 by quantitative microdialysis, showing rapid equilibration across the BBB; this supports CNS access for the query's chlorophenyl amide motif.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "AH-7921, an amide-containing molecule with a chlorophenyl group, showed a rat brain-to-plasma ratio of 16.6, demonstrating that amide-based small molecules can achieve high CNS exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "[11C]GSK931145, a benzamide PET tracer with a phenyl substituent, showed good brain penetration in pigs, supporting the ability of amide-containing molecules with similar aromatic features to cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "[11C]KTP-Me, a lipophilic chiral methyl-phenyl ester/ketone analogue, entered the human brain in a first-in-human PET study, providing direct human evidence that this structural class achieves CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass: multiple high-transfer direct CNS-exposure measurements in humans and rodents—CSF detection, Kp,uu values near or above 1, high brain-to-plasma ratios, and PET brain entry—consistently indicate that close analogues sharing the chiral phenethyl and chlorophenyl-amide features achieve meaningful brain access. No evidence points to inadequate CNS penetration.",
  "evidence_gaps": [
    "No direct experimental BBB/PK measurement for the exact query molecule.",
    "No explicit P-gp/BCRP efflux-transporter data for the query.",
    "Most high-transfer analogues contain a basic amine, ester, or ketone rather than the query's bis-amide, so passive permeability may differ somewhat.",
    "Human direct evidence is limited to one analogue."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

